#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <utility>
#include <cstring>
using namespace std;

using PII = pair<int, int>;

const int MAX_N = 11;
const int INF = 1000000000;
const int MAX_NODES = 2 * MAX_N * MAX_N;

struct Edge {
    int dest;
    int cap;
    int flow;
    int rev;
    Edge() {}
    Edge(int d, int c, int f, int r) : dest(d), cap(c), flow(f), rev(r) {}
};

vector<Edge> adj[MAX_NODES];
int level[MAX_NODES];
int ptr[MAX_NODES];
int src, dst, gridN;
queue<int> q;

void add_edge(int u, int v, int c) {
    adj[u].emplace_back(v, c, 0, adj[v].size());
    adj[v].emplace_back(u, 0, 0, adj[u].size() - 1);
}

bool bfs_levels() {
    fill(level, level + dst + 1, INF);
    level[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const Edge& e : adj[u]) {
            int v = e.dest;
            int rc = e.cap - e.flow;
            if (level[v] == INF && rc > 0) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[dst] != INF;
}

int dfs_flow(int u, int flow) {
    if (u == dst) return flow;
    for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
        Edge& e = adj[u][i];
        int v = e.dest;
        int rc = e.cap - e.flow;
        if (level[v] == level[u] + 1 && rc > 0) {
            int pushed = dfs_flow(v, min(flow, rc));
            if (pushed > 0) {
                e.flow += pushed;
                adj[v][e.rev].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int dinic_maxflow() {
    int result = 0;
    while (bfs_levels()) {
        memset(ptr, 0, sizeof(ptr));
        int f;
        while ((f = dfs_flow(src, INF)) > 0) result += f;
    }
    return result;
}

queue<PII> q_bfs;
const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};
int dist[MAX_N][MAX_N][MAX_N][MAX_N];
int time_threshold;
char matA[MAX_N][MAX_N], matB[MAX_N][MAX_N];
PII forbidden;

bool valid_pos(PII p) {
    int x = p.first, y = p.second;
    return x >= 0 && x < gridN && y >= 0 && y < gridN && matA[x][y] != 'Y' && matA[x][y] != 'Z';
}

void bfs_fill(int sx, int sy) {
    for (int i = 0; i < gridN; ++i)
        for (int j = 0; j < gridN; ++j)
            dist[sx][sy][i][j] = INF;
    dist[sx][sy][sx][sy] = 0;
    q_bfs.push({sx, sy});
    while (!q_bfs.empty()) {
        PII cur = q_bfs.front(); q_bfs.pop();
        if (dist[sx][sy][cur.first][cur.second] == dist[forbidden.first][forbidden.second][cur.first][cur.second] && (forbidden.first != sx || forbidden.second != sy)) continue;
        for (int k = 0; k < 4; ++k) {
            PII nxt = {cur.first + dx[k], cur.second + dy[k]};
            if (valid_pos(nxt) && dist[sx][sy][nxt.first][nxt.second] == INF && dist[sx][sy][cur.first][cur.second] + 1 <= dist[forbidden.first][forbidden.second][nxt.first][nxt.second]) {
                dist[sx][sy][nxt.first][nxt.second] = dist[sx][sy][cur.first][cur.second] + 1;
                q_bfs.push(nxt);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> gridN >> time_threshold;
    int px = -1, py = -1;
    for (int i = 0; i < gridN; ++i) {
        for (int j = 0; j < gridN; ++j) {
            cin >> matA[i][j];
            if (matA[i][j] == 'Z') { px = i; py = j; }
        }
    }
    for (int i = 0; i < gridN; ++i)
        for (int j = 0; j < gridN; ++j)
            cin >> matB[i][j];
    forbidden = {px, py};
    bfs_fill(px, py);
    for (int i = 0; i < gridN; ++i)
        for (int j = 0; j < gridN; ++j)
            dist[forbidden.first][forbidden.second][i][j] = min(dist[forbidden.first][forbidden.second][i][j], time_threshold);
    for (int i = 0; i < gridN; ++i)
        for (int j = 0; j < gridN; ++j)
            if (valid_pos({i, j})) bfs_fill(i, j);
    src = 0;
    dst = 2 * gridN * gridN + 1;
    for (int i = 0; i < gridN; ++i) {
        for (int j = 0; j < gridN; ++j) {
            if (matA[i][j] != '0') {
                add_edge(src, i * gridN + j + 1, matA[i][j] - '0');
            }
            if (matB[i][j] != '0') {
                add_edge(i * gridN + j + 1 + gridN * gridN, dst, matB[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < gridN; ++i) {
        for (int j = 0; j < gridN; ++j) {
            for (int i1 = 0; i1 < gridN; ++i1) {
                for (int j1 = 0; j1 < gridN; ++j1) {
                    if (valid_pos({i, j}) && valid_pos({i1, j1}) && dist[i][j][i1][j1] <= dist[px][py][i1][j1]) {
                        add_edge(i * gridN + j + 1, i1 * gridN + j1 + 1 + gridN * gridN, INF);
                    }
                }
            }
        }
    }
    cout << dinic_maxflow() << '\n';
    return 0;
}
